import React, { useEffect, useRef, useState } from "react"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

function easeIn(t) {
    return t * t
}

function easeOut(t) {
    const p = t - 1
    return 1 - p * p
}

function easeInOut(t) {
    return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t
}

function linearEasing(t) {
    return t
}

/**
 * @framerDisableUnlink
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
export default function PathFollower({
    pathData,
    animation,
    initialState,
    showPath,
    pathColor,
    pathThickness,
    content,
}) {
    const isCanvas = RenderTarget.current() === RenderTarget.canvas
    const containerRef = useRef(null)
    const elementSizes = useRef({})
    const [pathBounds, setPathBounds] = useState({ width: 200, height: 200 })
    const [scale, setScale] = useState(1)
    const [activeAnimations, setActiveAnimations] = useState([])

    const instances = Array.isArray(content)
        ? content
        : content
          ? [content]
          : []
    const hasInstances = instances.length > 0

    useEffect(() => {
        const svgNamespace = "http://www.w3.org/2000/svg"
        const tempSvg = document.createElementNS(svgNamespace, "svg")
        const newPath = document.createElementNS(svgNamespace, "path")
        newPath.setAttribute("d", pathData)
        tempSvg.appendChild(newPath)
        document.body.appendChild(tempSvg)

        const bbox = newPath.getBBox()
        setPathBounds({
            width: bbox.width + bbox.x * 2,
            height: bbox.height + bbox.y * 2,
        })

        document.body.removeChild(tempSvg)
    }, [pathData])

    useEffect(() => {
        if (!containerRef.current) return

        const updateScale = () => {
            const container = containerRef.current
            const containerWidth = container.offsetWidth
            const containerHeight = container.offsetHeight

            const scaleX = containerWidth / pathBounds.width
            const scaleY = containerHeight / pathBounds.height
            const newScale = Math.min(scaleX, scaleY, 1)

            setScale(newScale)
        }

        updateScale()

        const resizeObserver = new ResizeObserver(updateScale)
        resizeObserver.observe(containerRef.current)

        return () => {
            resizeObserver.disconnect()
        }
    }, [pathBounds])

    useEffect(() => {
        if (!hasInstances || isCanvas) return

        const svgNamespace = "http://www.w3.org/2000/svg"
        const tempSvg = document.createElementNS(svgNamespace, "svg")
        const newPath = document.createElementNS(svgNamespace, "path")
        newPath.setAttribute("d", pathData)
        tempSvg.appendChild(newPath)
        document.body.appendChild(tempSvg)
        const pathLength = newPath.getTotalLength()
        document.body.removeChild(tempSvg)

        const easingFunction =
            {
                linear: linearEasing,
                easeIn: easeIn,
                easeOut: easeOut,
                easeInOut: easeInOut,
            }[animation.easingType] || linearEasing

        let animationFrameID = null
        const globalStartTime = performance.now()
        const repeatCycle = Math.max(
            instances.length * animation.instanceDelay * 1000,
            animation.instanceDelay * 1000
        )
        const entranceDuration = initialState.duration * 1000
        const exitDuration = initialState.applyToExit
            ? initialState.duration * 1000
            : 0

        const animate = (timestamp) => {
            const elapsed = timestamp - globalStartTime
            const animations = []

            instances.forEach((instance, instanceIndex) => {
                const firstStart =
                    (animation.startDelay +
                        instanceIndex * animation.instanceDelay) *
                    1000

                let cycleNumber = 0
                while (true) {
                    const cycleStartTime =
                        firstStart + cycleNumber * repeatCycle
                    const timeSinceStart = elapsed - cycleStartTime
                    const totalDuration = animation.duration * 1000

                    if (timeSinceStart < 0) break

                    if (timeSinceStart <= totalDuration) {
                        const progress = timeSinceStart / totalDuration
                        const easedProgress = easingFunction(progress)
                        const point = newPath.getPointAtLength(
                            easedProgress * pathLength
                        )

                        let entranceProgress = 1
                        if (timeSinceStart < entranceDuration) {
                            entranceProgress = timeSinceStart / entranceDuration
                        }

                        let exitProgress = 1
                        if (
                            initialState.applyToExit &&
                            timeSinceStart > totalDuration - exitDuration
                        ) {
                            const timeUntilEnd = totalDuration - timeSinceStart
                            exitProgress = timeUntilEnd / exitDuration
                        }

                        const currentOpacity =
                            initialState.opacity +
                            (1 - initialState.opacity) *
                                entranceProgress *
                                exitProgress

                        const currentScale =
                            initialState.size +
                            (1 - initialState.size) *
                                entranceProgress *
                                exitProgress

                        animations.push({
                            id: `${instanceIndex}-${cycleNumber}`,
                            instanceIndex: instanceIndex,
                            instance: instance,
                            x: point.x * scale,
                            y: point.y * scale,
                            opacity: currentOpacity,
                            scale: currentScale,
                        })
                    }

                    if (!animation.loop) break
                    cycleNumber++

                    if (cycleStartTime > elapsed + totalDuration) break
                }
            })

            setActiveAnimations(animations)

            if (animation.loop || animations.length > 0) {
                animationFrameID = requestAnimationFrame(animate)
            }
        }

        animationFrameID = requestAnimationFrame(animate)

        return () => {
            if (animationFrameID) cancelAnimationFrame(animationFrameID)
        }
    }, [
        pathData,
        animation,
        initialState,
        hasInstances,
        isCanvas,
        scale,
        instances.length,
    ])

    const handleElementRef = (el, instanceIndex) => {
        if (el && !elementSizes.current[instanceIndex]) {
            const rect = el.getBoundingClientRect()
            elementSizes.current[instanceIndex] = {
                width: rect.width,
                height: rect.height,
            }
        }
    }

    const containerStyle = {
        position: "relative",
        width: "100%",
        height: "100%",
        minWidth: `${pathBounds.width}px`,
        minHeight: `${pathBounds.height}px`,
        overflow: "visible",
    }

    const svgStyle = {
        position: "absolute",
        top: 0,
        left: 0,
        width: `${pathBounds.width * scale}px`,
        height: `${pathBounds.height * scale}px`,
        overflow: "visible",
        pointerEvents: "none",
    }

    if (!hasInstances) {
        return (
            <div
                style={{
                    width: "100%",
                    height: "100%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                }}
            >
                <div
                    style={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                        textAlign: "center",
                        justifyContent: "center",
                        backgroundColor: "rgba(153, 102, 255, 0.1)",
                        padding: 40,
                        gap: 12,
                        borderRadius: 8,
                    }}
                >
                    <span role="img" aria-label="icon" style={{ fontSize: 32 }}>
                        🛤️
                    </span>
                    <div>
                        <h3
                            style={{
                                margin: 0,
                                fontSize: 14,
                                color: "#96F",
                                fontWeight: 600,
                            }}
                        >
                            Path Follower
                        </h3>
                        <p
                            style={{
                                margin: "4px 0 0 0",
                                fontSize: 12,
                                color: "rgba(153, 102, 255, 0.7)",
                            }}
                        >
                            Connect content to animate along path
                        </p>
                    </div>
                </div>
            </div>
        )
    }

    return (
        <div ref={containerRef} style={containerStyle}>
            {showPath && (
                <svg
                    style={svgStyle}
                    viewBox={`0 0 ${pathBounds.width} ${pathBounds.height}`}
                    preserveAspectRatio="xMidYMid meet"
                >
                    <path
                        d={pathData}
                        fill="none"
                        stroke={pathColor}
                        strokeWidth={pathThickness}
                    />
                </svg>
            )}
            {!isCanvas &&
                instances.map((instance, index) => (
                    <div
                        key={`measure-${index}`}
                        ref={(el) => handleElementRef(el, index)}
                        style={{
                            position: "absolute",
                            visibility: "hidden",
                            pointerEvents: "none",
                        }}
                    >
                        {instance}
                    </div>
                ))}
            {!isCanvas &&
                activeAnimations.map((anim) => {
                    const size = elementSizes.current[anim.instanceIndex] || {
                        width: 0,
                        height: 0,
                    }
                    const offsetX = anim.x - size.width / 2
                    const offsetY = anim.y - size.height / 2

                    return (
                        <div
                            key={anim.id}
                            style={{
                                position: "absolute",
                                left: 0,
                                top: 0,
                                transform: `translate(${offsetX}px, ${offsetY}px) scale(${anim.scale})`,
                                opacity: anim.opacity,
                                willChange: "transform, opacity",
                            }}
                        >
                            {anim.instance}
                        </div>
                    )
                })}
        </div>
    )
}

PathFollower.defaultProps = {
    pathData: "M10 80 Q 95 10 180 80",
    animation: {
        duration: 2,
        startDelay: 0,
        instanceDelay: 0.5,
        easingType: "linear",
        loop: true,
        mirror: false,
    },
    initialState: {
        opacity: 1,
        size: 1,
        duration: 0,
        applyToExit: false,
    },
    showPath: true,
    pathColor: "#000000",
    pathThickness: 2,
}

addPropertyControls(PathFollower, {
    content: {
        type: ControlType.Array,
        control: {
            type: ControlType.ComponentInstance,
        },
        title: "Content",
        maxCount: 10,
    },
    pathData: {
        type: ControlType.String,
        title: "Path Data",
        defaultValue: "M10 80 Q 95 10 180 80",
        displayTextArea: true,
    },
    animation: {
        type: ControlType.Object,
        title: "Animation",
        controls: {
            duration: {
                type: ControlType.Number,
                title: "Duration",
                min: 0.1,
                max: 30,
                step: 0.1,
                defaultValue: 2,
                unit: "s",
            },
            startDelay: {
                type: ControlType.Number,
                title: "Start Delay",
                min: 0,
                max: 10,
                step: 0.1,
                defaultValue: 0,
                unit: "s",
            },
            instanceDelay: {
                type: ControlType.Number,
                title: "Instance Delay",
                min: 0,
                max: 5,
                step: 0.1,
                defaultValue: 0.5,
                unit: "s",
            },
            easingType: {
                type: ControlType.Enum,
                title: "Easing Type",
                options: ["linear", "easeIn", "easeOut", "easeInOut"],
                optionTitles: ["Linear", "Ease In", "Ease Out", "Ease In Out"],
                defaultValue: "linear",
            },
            loop: {
                type: ControlType.Boolean,
                title: "Loop",
                defaultValue: true,
                enabledTitle: "Enabled",
                disabledTitle: "Disabled",
            },
            mirror: {
                type: ControlType.Boolean,
                title: "Mirror Loop",
                defaultValue: false,
                enabledTitle: "Yes",
                disabledTitle: "No",
            },
        },
    },
    initialState: {
        type: ControlType.Object,
        title: "Initial State",
        controls: {
            opacity: {
                type: ControlType.Number,
                title: "Opacity",
                min: 0,
                max: 1,
                step: 0.01,
                defaultValue: 1,
            },
            size: {
                type: ControlType.Number,
                title: "Size",
                min: 0,
                max: 2,
                step: 0.01,
                defaultValue: 1,
            },
            duration: {
                type: ControlType.Number,
                title: "Duration",
                min: 0,
                max: 5,
                step: 0.1,
                defaultValue: 0,
                unit: "s",
            },
            applyToExit: {
                type: ControlType.Boolean,
                title: "Apply to Exit",
                defaultValue: false,
                enabledTitle: "Yes",
                disabledTitle: "No",
            },
        },
    },
    showPath: {
        type: ControlType.Boolean,
        title: "Show Path",
        defaultValue: true,
        enabledTitle: "Show",
        disabledTitle: "Hide",
    },
    pathColor: {
        type: ControlType.Color,
        title: "Path Color",
        defaultValue: "#000000",
    },
    pathThickness: {
        type: ControlType.Number,
        title: "Path Thickness",
        min: 0.5,
        max: 20,
        step: 0.5,
        defaultValue: 2,
        unit: "px",
        description: "v1.0 \n[via SegmentUI](https://www.segmentUI.com)",
    },
})
